        depth: usize,
    ) -> Result<(), String> {
        const MAX_DEPTH: usize = 5;

        if depth > MAX_DEPTH {
            return Err(format!(
                "Requirement dependency chain exceeds max depth of {} for '{}'",
                MAX_DEPTH, requirement
            ));
